unsafe extern "C" fn get_feature(
    mut feature_id: crate::expat_h::XML_FeatureEnum,
    mut presult: *mut ::core::ffi::c_long,
) -> crate::expat_h::XML_Status {
    let mut feature: *const crate::expat_h::XML_Feature =
        crate::src::lib::xmlparse::XML_GetFeatureList() as *const crate::expat_h::XML_Feature;
    if feature.is_null() {
        return crate::expat_h::XML_STATUS_ERROR;
    }
    while (*feature).feature as ::core::ffi::c_uint
        != crate::expat_h::XML_FEATURE_END as ::core::ffi::c_int as ::core::ffi::c_uint
    {
        if (*feature).feature as ::core::ffi::c_uint == feature_id as ::core::ffi::c_uint {
            *presult = (*feature).value;
            return crate::expat_h::XML_STATUS_OK;
        }
        feature = feature.offset(1);
    }
    return crate::expat_h::XML_STATUS_ERROR;
}

