unsafe extern "C" fn test_big_tokens_scale_linearly() {
    crate::src::tests::minicheck::_check_set_test_info(
        b"test_big_tokens_scale_linearly\0".as_ptr() as *const ::core::ffi::c_char,
        b"/mnt/ssd1/ahomescu/development/immunant/libexpat/expat/tests/basic_tests.c\0".as_ptr()
            as *const ::core::ffi::c_char,
        5661 as ::core::ffi::c_int,
    );
    let text: [C2Rust_Unnamed_10; 5] = [
        C2Rust_Unnamed_10 {
            pre: b"<a>\0".as_ptr() as *const ::core::ffi::c_char,
            post: b"</a>\0".as_ptr() as *const ::core::ffi::c_char,
        },
        C2Rust_Unnamed_10 {
            pre: b"<b><![CDATA[ value: \0".as_ptr() as *const ::core::ffi::c_char,
            post: b" ]]></b>\0".as_ptr() as *const ::core::ffi::c_char,
        },
        C2Rust_Unnamed_10 {
            pre: b"<c attr='\0".as_ptr() as *const ::core::ffi::c_char,
            post: b"'></c>\0".as_ptr() as *const ::core::ffi::c_char,
        },
        C2Rust_Unnamed_10 {
            pre: b"<d><!-- \0".as_ptr() as *const ::core::ffi::c_char,
            post: b" --></d>\0".as_ptr() as *const ::core::ffi::c_char,
        },
        C2Rust_Unnamed_10 {
            pre: b"<e><\0".as_ptr() as *const ::core::ffi::c_char,
            post: b"/></e>\0".as_ptr() as *const ::core::ffi::c_char,
        },
    ];
    let num_cases: ::core::ffi::c_int = (::core::mem::size_of::<[C2Rust_Unnamed_10; 5]>() as usize)
        .wrapping_div(::core::mem::size_of::<C2Rust_Unnamed_10>() as usize)
        as ::core::ffi::c_int;
    let mut aaaaaa: [::core::ffi::c_char; 4096] = [0; 4096];
    let fillsize: ::core::ffi::c_int =
        ::core::mem::size_of::<[::core::ffi::c_char; 4096]>() as ::core::ffi::c_int;
    let fillcount: ::core::ffi::c_int = 100 as ::core::ffi::c_int;
    let approx_bytes: ::core::ffi::c_uint = (fillsize * fillcount) as ::core::ffi::c_uint;
    let max_factor: ::core::ffi::c_uint = 4 as ::core::ffi::c_uint;
    let max_scanned: ::core::ffi::c_uint = max_factor.wrapping_mul(approx_bytes);
    crate::stdlib::memset(
        &raw mut aaaaaa as *mut ::core::ffi::c_char as *mut ::core::ffi::c_void,
        'a' as i32,
        fillsize as crate::__stddef_size_t_h::size_t,
    );
    if crate::src::lib::xmlparse::g_reparseDeferralEnabledDefault == 0 {
        return;
    }
    let mut i: ::core::ffi::c_int = 0 as ::core::ffi::c_int;
    while i < num_cases {
        let mut parser: crate::expat_h::XML_Parser =
            crate::src::lib::xmlparse::XML_ParserCreate(::core::ptr::null::<
                crate::expat_external_h::XML_Char,
            >());
        if parser.is_null() {
            crate::src::tests::minicheck::_fail(
                b"/mnt/ssd1/ahomescu/development/immunant/libexpat/expat/tests/basic_tests.c\0"
                    .as_ptr() as *const ::core::ffi::c_char,
                5688 as ::core::ffi::c_int,
                b"check failed: parser != NULL\0".as_ptr() as *const ::core::ffi::c_char,
            );
        }
        let mut status: crate::expat_h::XML_Status = crate::expat_h::XML_STATUS_ERROR;
        crate::src::tests::minicheck::set_subtest(
            b"text=\"%saaaaaa%s\"\0".as_ptr() as *const ::core::ffi::c_char,
            text[i as usize].pre,
            text[i as usize].post,
        );
        crate::src::lib::xmlparse::g_bytesScanned = 0 as ::core::ffi::c_uint;
        status = crate::src::tests::common::_XML_Parse_SINGLE_BYTES(
            parser,
            text[i as usize].pre,
            crate::stdlib::strlen(text[i as usize].pre) as ::core::ffi::c_int,
            crate::expat_h::XML_FALSE as ::core::ffi::c_int,
        );
        if status as ::core::ffi::c_uint
            != crate::expat_h::XML_STATUS_OK as ::core::ffi::c_int as ::core::ffi::c_uint
        {
            crate::src::tests::common::_xml_failure(
                parser,
                b"/mnt/ssd1/ahomescu/development/immunant/libexpat/expat/tests/basic_tests.c\0"
                    .as_ptr() as *const ::core::ffi::c_char,
                5697 as ::core::ffi::c_int,
            );
        }
        let mut past_max_count: ::core::ffi::c_uint = 0 as ::core::ffi::c_uint;
        let mut f: ::core::ffi::c_int = 0 as ::core::ffi::c_int;
        while f < fillcount {
            status = crate::src::tests::common::_XML_Parse_SINGLE_BYTES(
                parser,
                &raw mut aaaaaa as *mut ::core::ffi::c_char,
                fillsize,
                crate::expat_h::XML_FALSE as ::core::ffi::c_int,
            );
            if status as ::core::ffi::c_uint
                != crate::expat_h::XML_STATUS_OK as ::core::ffi::c_int as ::core::ffi::c_uint
            {
                crate::src::tests::common::_xml_failure(
                    parser,
                    b"/mnt/ssd1/ahomescu/development/immunant/libexpat/expat/tests/basic_tests.c\0"
                        .as_ptr() as *const ::core::ffi::c_char,
                    5705 as ::core::ffi::c_int,
                );
            }
            if crate::src::lib::xmlparse::g_bytesScanned > max_scanned {
                let pushed: ::core::ffi::c_uint = (crate::stdlib::strlen(text[i as usize].pre)
                    as ::core::ffi::c_uint)
                    .wrapping_add(
                        ((f + 1 as ::core::ffi::c_int) * fillsize) as ::core::ffi::c_uint,
                    );
                crate::stdlib::fprintf(
                    crate::stdlib::stderr,
                    b"after %d/%d loops: pushed=%u scanned=%u (factor ~%.2f) max_scanned: %u (factor ~%u)\n\0"
                        .as_ptr() as *const ::core::ffi::c_char,
                    f + 1 as ::core::ffi::c_int,
                    fillcount,
                    pushed,
                    crate::src::lib::xmlparse::g_bytesScanned,
                    crate::src::lib::xmlparse::g_bytesScanned as ::core::ffi::c_double
                        / pushed as ::core::ffi::c_double,
                    max_scanned,
                    max_factor,
                );
                past_max_count = past_max_count.wrapping_add(1);
                if !(past_max_count < 5 as ::core::ffi::c_uint) {
                    crate::src::tests::minicheck::_fail(
                        b"/mnt/ssd1/ahomescu/development/immunant/libexpat/expat/tests/basic_tests.c\0"
                            .as_ptr() as *const ::core::ffi::c_char,
                        5720 as ::core::ffi::c_int,
                        b"check failed: past_max_count < 5\0".as_ptr()
                            as *const ::core::ffi::c_char,
                    );
                }
            }
            f += 1;
        }
        status = crate::src::tests::common::_XML_Parse_SINGLE_BYTES(
            parser,
            text[i as usize].post,
            crate::stdlib::strlen(text[i as usize].post) as ::core::ffi::c_int,
            crate::expat_h::XML_TRUE as ::core::ffi::c_int,
        );
        if status as ::core::ffi::c_uint
            != crate::expat_h::XML_STATUS_OK as ::core::ffi::c_int as ::core::ffi::c_uint
        {
            crate::src::tests::common::_xml_failure(
                parser,
                b"/mnt/ssd1/ahomescu/development/immunant/libexpat/expat/tests/basic_tests.c\0"
                    .as_ptr() as *const ::core::ffi::c_char,
                5728 as ::core::ffi::c_int,
            );
        }
        if !(crate::src::lib::xmlparse::g_bytesScanned > approx_bytes) {
            crate::src::tests::minicheck::_fail(
                b"/mnt/ssd1/ahomescu/development/immunant/libexpat/expat/tests/basic_tests.c\0"
                    .as_ptr() as *const ::core::ffi::c_char,
                5731 as ::core::ffi::c_int,
                b"check failed: g_bytesScanned > approx_bytes\0".as_ptr()
                    as *const ::core::ffi::c_char,
            );
        }
        if crate::src::lib::xmlparse::g_bytesScanned > max_scanned {
            crate::stdlib::fprintf(
                crate::stdlib::stderr,
                b"after all input: scanned=%u (factor ~%.2f) max_scanned: %u (factor ~%u)\n\0"
                    .as_ptr() as *const ::core::ffi::c_char,
                crate::src::lib::xmlparse::g_bytesScanned,
                crate::src::lib::xmlparse::g_bytesScanned as ::core::ffi::c_double
                    / approx_bytes as ::core::ffi::c_double,
                max_scanned,
                max_factor,
            );
            crate::src::tests::minicheck::_fail(
                b"/mnt/ssd1/ahomescu/development/immunant/libexpat/expat/tests/basic_tests.c\0"
                    .as_ptr() as *const ::core::ffi::c_char,
                5738 as ::core::ffi::c_int,
                b"scanned too many bytes\0".as_ptr() as *const ::core::ffi::c_char,
            );
        }
        crate::src::lib::xmlparse::XML_ParserFree(parser);
        i += 1;
    }
}

