static mut g_totalAlloc: crate::__stddef_size_t_h::size_t = 0 as crate::__stddef_size_t_h::size_t;

static mut g_biggestAlloc: crate::__stddef_size_t_h::size_t = 0 as crate::__stddef_size_t_h::size_t;

unsafe extern "C" fn counting_realloc(
    mut ptr: *mut ::core::ffi::c_void,
    mut size: crate::__stddef_size_t_h::size_t,
) -> *mut ::core::ffi::c_void {
    g_totalAlloc = g_totalAlloc.wrapping_add(size);
    if size > g_biggestAlloc {
        g_biggestAlloc = size;
    }
    return crate::stdlib::realloc(ptr, size);
}

unsafe extern "C" fn counting_malloc(
    mut size: crate::__stddef_size_t_h::size_t,
) -> *mut ::core::ffi::c_void {
    return counting_realloc(crate::__stddef_null_h::NULL, size);
}

